"""Render slide PNGs for what-is-mam.

Usage:
    python py/main_render_slides.py               # render all slides
    python py/main_render_slides.py title-card    # render one slide by name
"""

import argparse
import pathlib

from bidi.algorithm import get_display
from PIL import Image, ImageDraw, ImageFont

W, H = 2560, 1440
FONT_DIR = pathlib.Path("C:/Windows/Fonts")
DEST_DIR = pathlib.Path("doc/what-is-mam-img")


def _make_gradient(top_rgb, bot_rgb):
    """Return a W×H image filled with a vertical linear gradient."""
    img = Image.new("RGB", (W, H))
    from PIL import ImageDraw as _D

    draw = _D.ImageDraw(img)
    for y in range(H):
        t = y / (H - 1)
        r = int(top_rgb[0] + (bot_rgb[0] - top_rgb[0]) * t)
        g = int(top_rgb[1] + (bot_rgb[1] - top_rgb[1]) * t)
        b = int(top_rgb[2] + (bot_rgb[2] - top_rgb[2]) * t)
        draw.line([(0, y), (W, y)], fill=(r, g, b))
    return img


def _draw_centered_lines(img, lines, gap_after):
    """Draw a vertical stack of text lines, centered on the image.

    lines     — list of (text, font, color_rgb)
    gap_after — list of pixel gaps after each line (last entry unused)
    """
    draw = ImageDraw.Draw(img)
    bboxes = [draw.textbbox((0, 0), text, font=font) for text, font, _ in lines]
    line_heights = [bb[3] - bb[1] for bb in bboxes]
    n = len(lines)
    advance_to_last = sum(line_heights[i] + gap_after[i] for i in range(n - 1))
    # Start Y so the visual ink block is centered
    y = H // 2 - (bboxes[0][1] + advance_to_last + bboxes[-1][3]) // 2
    for i, ((text, font, color), bb) in enumerate(zip(lines, bboxes)):
        text_w = bb[2] - bb[0]
        x = (W - text_w) // 2 - bb[0]
        draw.text((x, y), text, font=font, fill=color)
        y += line_heights[i] + gap_after[i]


def render_title_card():
    """Render slide-title-card.png."""
    font_bold = ImageFont.truetype(str(FONT_DIR / "arialbd.ttf"), size=180)
    font_reg = ImageFont.truetype(str(FONT_DIR / "arial.ttf"), size=96)
    lines = [
        ("What is MAM?", font_bold, (255, 255, 255)),
        ("Miqra According to the Masorah", font_reg, (200, 232, 228)),
        # מקרא על פי המסורה — bidi-reordered so Pillow renders RTL correctly
        (
            get_display(
                "\u05de\u05e7\u05e8\u05d0 \u05e2\u05dc \u05e4\u05d9 \u05d4\u05de\u05e1\u05d5\u05e8\u05d4"
            ),
            font_reg,
            (200, 232, 228),
        ),
    ]
    img = _make_gradient((13, 94, 87), (8, 61, 56))
    _draw_centered_lines(img, lines, gap_after=[80, 40, 0])
    dest = DEST_DIR / "slide-title-card.png"
    img.save(dest)
    print(f"Saved {dest} {img.size}")


# Registry of all slides: name -> render function
ALL_SLIDES = {
    "title-card": render_title_card,
}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "slide",
        nargs="?",
        choices=list(ALL_SLIDES),
        metavar="SLIDE",
        help=f"slide to render (one of: {', '.join(ALL_SLIDES)}); omit to render all",
    )
    args = parser.parse_args()
    targets = [args.slide] if args.slide else list(ALL_SLIDES)
    for name in targets:
        ALL_SLIDES[name]()


if __name__ == "__main__":
    main()
